using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;namespace ServiceTool{internal static class ServiceAuditUiTests{static System.Collections.Generic.IEnumerable<Control> Walk(Control p){foreach(Control c in p.Controls){yield return c;foreach(var x in Walk(c))yield return x;}}[STAThread]static int Main(){try{int n=0;foreach(bool dark in new[]{true,false})using(var form=new ServiceProbeForm("Audit preview",true)){form.SetTheme(dark,false);form.Show();for(int i=0;i<10;i++)Application.DoEvents();var controls=Walk(form).ToArray();if(controls.OfType<ComboBox>().Any())throw new Exception("Unexpected dropdown");n++;var buttons=controls.OfType<BrandButton>().Where(b=>new[]{"Проверить отклик","Открыть Swagger","Назад"}.Contains(b.Text)).ToArray();foreach(var button in buttons)Console.WriteLine(button.Text+" "+button.Size);if(buttons.Length!=3||buttons.Max(b=>b.Width)-buttons.Min(b=>b.Width)>1||buttons.Select(b=>b.Height).Distinct().Count()!=1)throw new Exception("Unequal actions");n++;using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"service-probe-"+dark+".png"));}}Console.WriteLine("PASS: "+n+" UI checks, preview only.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}}